package com.example.custombroadcast; import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; import android.widget.Toast; public class MyReceiver extends BroadcastReceiver { @Override public void onReceive(Context c,Intent i){String m=i.getStringExtra("message");Toast.makeText(c,"Custom Broadcast Received: "+m,Toast.LENGTH_LONG).show();}}
